<section class="page-hero shell compact"><span class="kicker">PANEL INTERNO</span><h1>Área de <em>operarios.</em></h1><p>Administra el progreso de fabricación y las solicitudes de taller de la demostración.</p></section><section class="section shell"><div class="staff-stats"><div class="surface"><small>Pedidos</small><strong><?= count($orders) ?></strong><span>Últimos 100</span></div><div class="surface"><small>Fabricaciones abiertas</small><strong><?= count(array_filter($orders, fn($o) => $o['status'] !== 'completed')) ?></strong><span>Por completar</span></div><div class="surface"><small>Solicitudes de taller</small><strong><?= count($repairs) ?></strong><span>Últimas 100</span></div><div class="surface"><small>Mensajes</small><strong><?= count($messages) ?></strong><span>Últimos 20</span></div></div><section class="space-top"><div class="section-heading"><h2>Órdenes de fabricación</h2><span>Selecciona un pedido para actualizarlo</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Operario asignado</th><th>Progreso</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td>#<?= (int) $order['id'] ?></td><td><?= e($order['customer_name']) ?></td><td><?= e($order['staff_name'] ?? 'Sin asignar') ?></td><td><?= (int) $order['done_steps'] ?>/7</td><td><span class="status status-<?= e($order['status']) ?>"><?= e(\App\Models\Order::STATUS[$order['status']] ?? $order['status']) ?></span></td><td><a href="/pedidos/<?= (int) $order['id'] ?>">Gestionar ↗</a></td></tr><?php endforeach; ?><?php if (!$orders): ?><tr><td colspan="6" class="muted">No hay pedidos por el momento.</td></tr><?php endif; ?></tbody></table></div></section><section class="space-top" id="taller"><div class="section-heading"><h2>Solicitudes de taller</h2><span>Avanza cada etapa de reparación</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>Cliente</th><th>Vehículo</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach ($repairs as $repair): ?><tr><td>#<?= (int) $repair['id'] ?></td><td><?= e($repair['customer_name']) ?></td><td><?= e($repair['make']) ?> <?= e($repair['model']) ?><small><?= e($repair['license_plate']) ?></small></td><td><span class="pill"><?= e(\App\Models\Repair::STATES[$repair['status']] ?? $repair['status']) ?></span></td><td><?php if ($repair['status'] !== 'delivered'): ?><form method="post" action="/operarios/taller/<?= (int) $repair['id'] ?>"><?= csrf_field() ?><button class="btn btn-small btn-secondary" type="submit">Avanzar ↗</button></form><?php else: ?>Finalizado<?php endif; ?></td></tr><?php endforeach; ?><?php if (!$repairs): ?><tr><td colspan="5" class="muted">No hay solicitudes de taller.</td></tr><?php endif; ?></tbody></table></div></section><section class="space-top"><div class="section-heading"><h2>Mensajes de contacto</h2><span>Últimos mensajes recibidos</span></div><div class="message-grid"><?php foreach ($messages as $message): ?><article class="surface"><span class="card-overline"><?= date_es($message['created_at']) ?></span><h3><?= e($message['name']) ?></h3><p><a href="mailto:<?= e($message['email']) ?>"><?= e($message['email']) ?></a></p><p><?= nl2br(e($message['message'])) ?></p></article><?php endforeach; ?><?php if (!$messages): ?><div class="empty-state surface"><p>No hay mensajes.</p></div><?php endif; ?></div></section></section>